documents = [
    {
        "text": "Quarterly Revenue Report\n\nThis document summarizes Q1 2026 revenue.",
        "file_metadata": {"author": "Finance Team", "created": "2026-04-01"},
    },
    {
        "text": "Employee Onboarding Guide\n\nWelcome to the company.",
        "file_metadata": {},
    },
]

def infer_title(text):
    # infer a title from the document's opening line
    first_line = text.split("\n")[0]
    return first_line.strip()

def build_metadata(doc):
    # start from whatever metadata the file already carries
    metadata = dict(doc["file_metadata"])
    if "title" not in metadata:
        metadata["title"] = infer_title(doc["text"])
    return metadata

for doc in documents:
    metadata = build_metadata(doc)
    print(f"Text preview: {doc['text'][:40]!r}")
    print(f"Metadata: {metadata}\n")
